// A Sphinx scores the types it can see: every card in the army except itself.
// So Sphinx is among those types exactly when a second Sphinx is present.
const typesSeenByASphinx = (army: Card[], sphinxCount: number): Set<string> => {
  const otherMonsters = army.filter((card) => !isSphinx(card));
  const typesSeen = new Set(otherMonsters.map((card) => card.monster));

  return sphinxCount > 1 ? new Set([...typesSeen, SPHINX]) : typesSeen;
};

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;
  const typeCount = typesSeenByASphinx(army, sphinxCount).size;

  return sphinxCount * (SPHINX_POINTS + bonusForVariety(typeCount));
};

